//! Cargo-driven `mshtml.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x715b0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fed7000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fed7000000u64)),
        o => panic!("mshtml-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:uuid", "engine:wine", "engine:c:strmiids", "engine:oldnames", "import:wininet", "import:urlmon", "import:shlwapi", "import:shell32", "import:ole32", "import:oleaut32", "import:user32", "import:gdi32", "import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "body"],
        "x86_64" => &["engine:uuid", "engine:wine", "engine:c:strmiids", "engine:oldnames", "import:wininet", "import:urlmon", "import:shlwapi", "import:shell32", "import:ole32", "import:oleaut32", "import:user32", "import:gdi32", "import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "body"],
        "aarch64" => &["engine:uuid", "engine:wine", "engine:c:strmiids", "engine:oldnames", "import:wininet", "import:urlmon", "import:shlwapi", "import:shell32", "import:ole32", "import:oleaut32", "import:user32", "import:gdi32", "import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "body"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/mshtml",
        "dll/win32/mshtml",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "COM_NO_WINDOWS_H",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x600",
        "__ROS_LONG64__",
        "__USE_CRTIMP",
        "__WINESRC__",
        "strcasecmp=_stricmp",
        "strncasecmp=_strnicmp",
    ];

    Linker::new(target_json)
        .c_from_compile_db("mshtml_shims", &["dll/win32/mshtml/conpoint.c", "dll/win32/mshtml/dispex.c", "dll/win32/mshtml/editor.c", "dll/win32/mshtml/hlink.c", "dll/win32/mshtml/htmlanchor.c", "dll/win32/mshtml/htmlarea.c", "dll/win32/mshtml/htmlattr.c", "dll/win32/mshtml/htmlbody.c", "dll/win32/mshtml/htmlcomment.c", "dll/win32/mshtml/htmlcurstyle.c", "dll/win32/mshtml/htmldoc.c", "dll/win32/mshtml/htmlelem.c", "dll/win32/mshtml/htmlelemcol.c", "dll/win32/mshtml/htmlembed.c", "dll/win32/mshtml/htmlevent.c", "dll/win32/mshtml/htmlform.c", "dll/win32/mshtml/htmlframe.c", "dll/win32/mshtml/htmlframebase.c", "dll/win32/mshtml/htmlgeneric.c", "dll/win32/mshtml/htmlhead.c", "dll/win32/mshtml/htmliframe.c", "dll/win32/mshtml/htmlimg.c", "dll/win32/mshtml/htmlinput.c", "dll/win32/mshtml/htmllink.c", "dll/win32/mshtml/htmllocation.c", "dll/win32/mshtml/htmlmeta.c", "dll/win32/mshtml/htmlnode.c", "dll/win32/mshtml/htmlobject.c", "dll/win32/mshtml/htmloption.c", "dll/win32/mshtml/htmlscreen.c", "dll/win32/mshtml/htmlscript.c", "dll/win32/mshtml/htmlselect.c", "dll/win32/mshtml/htmlstorage.c", "dll/win32/mshtml/htmlstyle.c", "dll/win32/mshtml/htmlstyle2.c", "dll/win32/mshtml/htmlstyle3.c", "dll/win32/mshtml/htmlstyleelem.c", "dll/win32/mshtml/htmlstylesheet.c", "dll/win32/mshtml/htmltable.c", "dll/win32/mshtml/htmltablecell.c", "dll/win32/mshtml/htmltablerow.c", "dll/win32/mshtml/htmltextarea.c", "dll/win32/mshtml/htmltextcont.c", "dll/win32/mshtml/htmltextnode.c", "dll/win32/mshtml/htmlwindow.c", "dll/win32/mshtml/ifacewrap.c", "dll/win32/mshtml/ipwindow.c", "dll/win32/mshtml/loadopts.c", "dll/win32/mshtml/main.c", "dll/win32/mshtml/mutation.c", "dll/win32/mshtml/navigate.c", "dll/win32/mshtml/npplugin.c", "dll/win32/mshtml/nsembed.c", "dll/win32/mshtml/nsevents.c", "dll/win32/mshtml/nsio.c", "dll/win32/mshtml/nsservice.c", "dll/win32/mshtml/olecmd.c", "dll/win32/mshtml/oleobj.c", "dll/win32/mshtml/olewnd.c", "dll/win32/mshtml/omnavigator.c", "dll/win32/mshtml/persist.c", "dll/win32/mshtml/pluginhost.c", "dll/win32/mshtml/propbag.c", "dll/win32/mshtml/protocol.c", "dll/win32/mshtml/script.c", "dll/win32/mshtml/secmgr.c", "dll/win32/mshtml/selection.c", "dll/win32/mshtml/service.c", "dll/win32/mshtml/task.c", "dll/win32/mshtml/txtrange.c", "dll/win32/mshtml/view.c", "dll/win32/mshtml/xmlhttprequest.c", "dll/win32/mshtml/guid.c"])
        .rc("dll/win32/mshtml/rsrc.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/mshtml/mshtml.spec", "mshtml.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/wininet/wininet.spec", "wininet.dll", "wininet")
        .import_lib("dll/win32/urlmon/urlmon.spec", "urlmon.dll", "urlmon")
        .import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("dll/win32/shell32/shell32.spec", "shell32.dll", "shell32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
